dynamic _dartActionEncode(dynamic value) {
 if (value == null) return null;
 if (value is DateTime) return value.toAxtonPrecision().toIso8601String();
 if (value is Enum) return value.name;
 if (value is List) return value.map(_dartActionEncode).toList();
 if (value is _DartActionRecord) return value.toRecord();
 if (value is Item) return value.toRecord();
 if (value is ItemCreateInput) return value.toCreateRecord();
 if (value is ItemIdentity) return value.toRecord();
 if (value is Tag) return value.toRecord();
 if (value is TagCreateInput) return value.toCreateRecord();
 if (value is TagIdentity) return value.toRecord();
 if (value is Seen) return value.toRecord();
 if (value is SeenCreateInput) return value.toCreateRecord();
 if (value is SeenIdentity) return value.toRecord();
 return value;
}
